vertex_shader.source:
uniform float time;
uniform float deform;
uniform int deformMode;
uniform vec4 modeParams1;
uniform vec3 modeParams2;

varying vec2 vUv;
varying vec3 vNormal;
varying float vNoise;

float hash(vec3 p){
  p = fract(p*0.3183099 + vec3(0.1,0.2,0.3));
  p *= 17.0;
  return fract(p.x*p.y*p.z*(p.x+p.y+p.z));
}

float noise(vec3 p){
  vec3 i=floor(p);
  vec3 f=fract(p);
  f=f*f*(3.0-2.0*f);
  return mix(
    mix(
      mix(hash(i+vec3(0.0)),hash(i+vec3(1.0,0.0,0.0)),f.x),
      mix(hash(i+vec3(0.0,1.0,0.0)),hash(i+vec3(1.0,1.0,0.0)),f.x),
      f.y
    ),
    mix(
      mix(hash(i+vec3(0.0,0.0,1.0)),hash(i+vec3(1.0,0.0,1.0)),f.x),
      mix(hash(i+vec3(0.0,1.0,1.0)),hash(i+vec3(1.0,1.0,1.0)),f.x),
      f.y
    ),
    f.z
  );
}

void main(){
  vUv = uv;
  vNormal = normalize(normal);
  vec3 pos = position;

  float deformScale = modeParams1.x;
  float freqScale   = modeParams1.y;
  float swirlScale  = modeParams1.z;
  float noiseScale  = modeParams1.w;

  float twistScale  = modeParams2.x;
  float gravityScale= modeParams2.y;
  float chaosScale  = modeParams2.z;

  float n = noise(pos*(2.0 + deform*0.5*noiseScale) + time*0.2);
  vNoise = n;

  float d = deform * deformScale;

  if (deformMode == 0) {
    pos += vNormal * n * d * 6.9;
    pos.x += sin(pos.y*9.0*freqScale + time*0.7)*d*0.09;
    pos.y += cos(pos.z*9.0*freqScale + time*0.6)*d*0.09;
    pos.z += sin(pos.x*10.0*freqScale+ time*0.8)*d*0.09;
  }
  else if (deformMode == 1) {
    float ang = d * 21.0 * n * twistScale;
    float s = sin(ang), c = cos(ang);
    pos = vec3(
      c*pos.x - s*pos.z,
      pos.y,
      s*pos.x + c*pos.z
    );
  }
  else if (deformMode == 2) {
    pos.y += sin(pos.x*9.0*freqScale + time*7.0)*d*0.5;
    pos.x += sin(pos.y*8.0*freqScale + time*5.5)*d*0.9;
  }
  else if (deformMode == 3) {
    float r = length(pos.xy);
    float ang = atan(pos.y,pos.x) + d * 29.0 * n * swirlScale;
    pos.x = r * cos(ang);
    pos.y = r * sin(ang);
    pos.z += d * 9.9 * n;
  }
  else if (deformMode == 4) {
    float cell = sin(pos.x*8.0*freqScale + pos.y*9.0*freqScale + pos.z*9.0*freqScale + time*4.0);
    pos += vNormal * cell * d * 9.15;
  }
  else if (deformMode == 5) {
    float impl = d * (0.9 + n*0.6);
    pos -= normalize(pos + vec3(0.0001)) * impl;
  }
  else if (deformMode == 6) {
    vec3 dir = normalize(pos + vec3(0.0001));
    float shard = step(0.7, n) * d * 0.9 * chaosScale;
    pos += dir * shard;
  }
  else if (deformMode == 7) {
    float k = d * 9.9;
    pos.x *= (1.0 + k * sin(time + n*5.0*freqScale));
    pos.y *= (1.0 + k * cos(time*0.8 + n*4.0*freqScale));
    pos.z *= (1.0 + k * sin(time*2.3 + n*3.0*freqScale));
  }
  else if (deformMode == 8) {
    float flow = sin(pos.y * 3.0*freqScale + time*4.0)*d*2.15;
    pos.x += flow * (n*2.0 - 1.0);
    pos.z += flow * (n*2.0 - 1.0);
    pos.y -= d * 0.2 * (0.5 + n) * gravityScale;
  }
  else if (deformMode == 9) {
    pos.x += sin(pos.y * 20.0*freqScale + time*5.0)*d*0.1;
    pos.y += sin(pos.z * 25.0*freqScale + time*4.0)*d*0.1;
    pos.z += sin(pos.x * 30.0*freqScale + time*3.0)*d*0.9;
    pos += vec3(n - 0.5) * d * 0.5 * chaosScale;
  }

  gl_Position = projectionMatrix * modelViewMatrix * vec4(pos,1.0);
}

fragment_shader.source:
uniform sampler2D map;
uniform float time;
uniform float deform;
varying vec2 vUv;
varying vec3 vNormal;
varying float vNoise;

void main(){
  vec4 tex = texture2D(map, vUv);
  vec3 light = normalize(vec3(0.3,1.0,0.4));
  float diff = 0.4 + 0.6*max(0.0, dot(vNormal, light));
  gl_FragColor = vec4(tex.rgb * diff, 1.0);
}
